CREATE OR REPLACE FUNCTION public.dawaa_customer_identity_key_v1(p_customer_id text, p_customer_code text, p_phone text, p_name text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  v_phone text := public.dawaa_normalize_egyptian_mobile_v1(p_phone);
  v_name text;
begin
  if nullif(btrim(p_customer_id), '') is not null then
    return 'id:' || btrim(p_customer_id);
  end if;
  if nullif(btrim(p_customer_code), '') is not null
     and lower(btrim(p_customer_code)) not in ('0','null','undefined','غير محدد','غير معروف') then
    return 'code:' || btrim(p_customer_code);
  end if;
  if v_phone ~ '^01[0125][0-9]{8}$' then
    return 'phone:' || v_phone;
  end if;
  v_name := lower(regexp_replace(btrim(coalesce(p_name, '')), '\s+', ' ', 'g'));
  if v_name <> '' and v_name not in ('0','غير محدد','غير معروف','عميل غير مسجل','عميل الصيدلية') then
    return 'name:' || v_name;
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.find_or_create_open_customer_followup(p_customer_id text, p_customer_code text, p_customer_name text, p_customer_phone text, p_branch text, p_request_type text, p_request_details text, p_followup_reason text, p_priority text, p_next_followup_date date, p_actor_staff_id text, p_actor_name text, p_client_request_id text DEFAULT NULL::text, p_source text DEFAULT 'manual'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_staff record;
  v_identity text;
  v_case_type text := coalesce(nullif(btrim(p_request_type), ''), 'general');
  v_branch text := nullif(btrim(p_branch), '');
  v_existing public.daily_followups%rowtype;
  v_created public.daily_followups%rowtype;
  v_lock_key text;
  v_today text := to_char(timezone('Africa/Cairo', now()), 'YYYY-MM-DD');
begin
  if nullif(btrim(p_actor_staff_id), '') is null then
    raise exception 'actor_staff_id_required';
  end if;

  select * into v_staff
  from public.resolve_staff_account_safe(p_actor_staff_id)
  limit 1;

  if v_staff.id is null or v_staff.active is not true or v_staff.can_login is not true then
    raise exception 'active_staff_account_required';
  end if;

  if coalesce(v_staff.role, '') not in (
    'customer_service','customer_service_manager','general_manager','branch_manager',
    'branches_manager','admin','doctor','pharmacist','shift_supervisor','shift_supervisor_evening'
  ) then
    raise exception 'followup_create_permission_denied';
  end if;

  v_identity := public.dawaa_customer_identity_key_v1(
    p_customer_id, p_customer_code, p_customer_phone, p_customer_name
  );
  if v_identity is null then
    raise exception 'customer_identity_required';
  end if;
  if v_branch is null then
    raise exception 'branch_required';
  end if;

  if nullif(btrim(p_client_request_id), '') is not null then
    select * into v_existing
    from public.daily_followups
    where client_request_id = btrim(p_client_request_id)
    limit 1;
    if v_existing.id is not null then
      return jsonb_build_object('followup_id', v_existing.id, 'created', false, 'idempotent_replay', true, 'identity_key', v_existing.identity_key);
    end if;
  end if;

  v_lock_key := v_identity || '|' || v_branch || '|' || v_case_type;
  perform pg_advisory_xact_lock(hashtextextended(v_lock_key, 0));

  select * into v_existing
  from public.daily_followups
  where identity_key = v_identity
    and branch = v_branch
    and coalesce(nullif(btrim(request_type), ''), 'general') = v_case_type
    and completed_at is null
    and cancelled_at is null
    and archived_at is null
    and is_hidden is false
    and duplicate_of is null
  order by created_at desc nulls last
  limit 1
  for update;

  if v_existing.id is not null then
    update public.daily_followups
      set updated_at = now(),
          next_followup_date = coalesce(p_next_followup_date, next_followup_date),
          priority = coalesce(nullif(btrim(p_priority), ''), priority)
    where id = v_existing.id;

    insert into public.customer_service_followup_events(
      followup_id, event_type, event_status, actor_staff_id, actor_name, notes, metadata
    ) values (
      v_existing.id,
      'request_linked',
      'open',
      p_actor_staff_id,
      coalesce(nullif(btrim(p_actor_name), ''), v_staff.name),
      coalesce(nullif(btrim(p_request_details), ''), nullif(btrim(p_followup_reason), ''), 'طلب متابعة إضافي'),
      jsonb_build_object(
        'source', coalesce(nullif(btrim(p_source), ''), 'manual'),
        'request_type', v_case_type,
        'client_request_id', nullif(btrim(p_client_request_id), ''),
        'requested_at', now()
      )
    );

    return jsonb_build_object('followup_id', v_existing.id, 'created', false, 'linked_to_open_case', true, 'identity_key', v_identity);
  end if;

  insert into public.daily_followups(
    date, customer_id, customer_name, name, phone, customer_phone, customer_code,
    branch, status, followup_status, contact_status, followup_type, request_type,
    request_details, followup_reason, priority, next_followup_date, created_by,
    created_by_name, requested_by_staff_id, request_source, identity_key,
    client_request_id, is_hidden, is_duplicate
  ) values (
    v_today, nullif(btrim(p_customer_id), ''), nullif(btrim(p_customer_name), ''),
    nullif(btrim(p_customer_name), ''), public.dawaa_normalize_egyptian_mobile_v1(p_customer_phone),
    public.dawaa_normalize_egyptian_mobile_v1(p_customer_phone), nullif(btrim(p_customer_code), ''),
    v_branch, 'not_started', 'pending', 'pending', v_case_type, v_case_type,
    nullif(btrim(p_request_details), ''), nullif(btrim(p_followup_reason), ''),
    coalesce(nullif(btrim(p_priority), ''), 'متوسطة'), p_next_followup_date,
    p_actor_staff_id, coalesce(nullif(btrim(p_actor_name), ''), v_staff.name),
    p_actor_staff_id, coalesce(nullif(btrim(p_source), ''), 'manual'), v_identity,
    nullif(btrim(p_client_request_id), ''), false, false
  ) returning * into v_created;

  insert into public.customer_service_followup_events(
    followup_id, event_type, event_status, actor_staff_id, actor_name, notes, metadata
  ) values (
    v_created.id, 'created', 'open', p_actor_staff_id,
    coalesce(nullif(btrim(p_actor_name), ''), v_staff.name),
    coalesce(nullif(btrim(p_request_details), ''), nullif(btrim(p_followup_reason), ''), 'إنشاء متابعة'),
    jsonb_build_object('source', coalesce(nullif(btrim(p_source), ''), 'manual'), 'request_type', v_case_type, 'client_request_id', nullif(btrim(p_client_request_id), ''))
  );

  return jsonb_build_object('followup_id', v_created.id, 'created', true, 'linked_to_open_case', false, 'identity_key', v_identity);
exception
  when unique_violation then
    if nullif(btrim(p_client_request_id), '') is not null then
      select * into v_existing from public.daily_followups where client_request_id = btrim(p_client_request_id) limit 1;
      if v_existing.id is not null then
        return jsonb_build_object('followup_id', v_existing.id, 'created', false, 'idempotent_replay', true, 'identity_key', v_existing.identity_key);
      end if;
    end if;
    raise;
end;
$function$

CREATE OR REPLACE FUNCTION public.dawaa_materialize_whatsapp_action_core_v2(p_action_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_action public.whatsapp_conversation_actions%rowtype;
  v_source public.whatsapp_review_sources%rowtype;
  v_result jsonb;
  v_target_id text;
  v_priority text;
  v_request_type text;
  v_needed_date date;
begin
  if public.dawaa_current_staff_account_id_strict() is null then
    raise exception 'not_authorized';
  end if;

  select * into v_action
  from public.whatsapp_conversation_actions
  where id = p_action_id
  for update;

  if v_action.id is null then raise exception 'whatsapp_action_not_found'; end if;

  select * into v_source from public.whatsapp_review_sources where id = v_action.source_id;
  if v_source.id is null then raise exception 'whatsapp_source_not_found'; end if;

  if not public.dawaa_can_read_conversation_review_row_v2(
    public.dawaa_current_staff_account_id_strict(), v_source.staff_id, null::uuid, v_source.branch, null::uuid
  ) then raise exception 'whatsapp_action_access_denied'; end if;

  if v_action.status = 'created' then
    return jsonb_build_object('ok',true,'already_created',true,'action_id',v_action.id,'target_table',v_action.target_table,'target_id',v_action.target_id);
  end if;
  if v_action.status not in ('ready','proposed') then raise exception 'whatsapp_action_not_materializable'; end if;

  if v_action.action_type = 'customer_request' then
    -- Explicit execution is required because customer request registration can trigger incentive credit.
    if v_action.status <> 'ready' or not v_action.auto_eligible then raise exception 'customer_request_requires_ready_verified_action'; end if;
    if v_action.customer_id is null then raise exception 'customer_request_customer_required'; end if;
    if v_action.product_id is null then raise exception 'customer_request_product_required'; end if;
    if v_action.staff_id is null then raise exception 'customer_request_doctor_required'; end if;
    v_priority := case when coalesce(v_action.payload->>'urgency','normal')='urgent' then 'urgent' else 'normal' end;
    v_request_type := coalesce(nullif(v_action.payload->>'request_type',''),'missing_medicine');
    v_needed_date := case when v_action.due_at is null then null else (v_action.due_at at time zone 'Africa/Cairo')::date end;
    v_result := public.create_customer_request_canonical_v2(
      v_action.customer_id, v_action.product_id, v_action.staff_id, v_action.branch,
      coalesce(v_action.quantity,1), v_priority, v_request_type, 'whatsapp', v_needed_date,
      null, null, concat_ws(E'\n',v_action.reason,'WhatsApp source: '||v_action.source_id::text), null, null
    );
    v_target_id := nullif(v_result->'request'->>'id','');
    if v_target_id is null then raise exception 'customer_request_creation_did_not_return_id'; end if;
    update public.whatsapp_conversation_actions set status='created',target_table='customer_requests',target_id=v_target_id,last_error=null,updated_at=now() where id=v_action.id;

  elsif v_action.action_type in ('customer_followup','recommendation_followup','complaint_followup') then
    if nullif(trim(coalesce(v_action.customer_name,'')),'') is null then raise exception 'followup_customer_name_required'; end if;
    if nullif(trim(coalesce(v_action.branch,'')),'') is null then raise exception 'followup_branch_required'; end if;
    v_request_type := case v_action.action_type when 'recommendation_followup' then 'recommendation' when 'complaint_followup' then 'complaint' else 'general' end;
    v_priority := case when v_action.action_type='complaint_followup' then 'عالية' when coalesce(v_action.payload->>'priority','')='urgent' then 'عالية' when coalesce(v_action.payload->>'priority','')='important' then 'متوسطة' else 'متوسطة' end;
    v_needed_date := case when v_action.due_at is null then null else (v_action.due_at at time zone 'Africa/Cairo')::date end;
    v_result := public.dawaa_create_or_link_customer_followup_v1(
      v_action.customer_id::text, v_action.customer_code, v_action.customer_name, v_action.customer_phone,
      v_action.branch, v_request_type,
      concat_ws(E'\n',v_action.reason,case when v_action.product_name is not null then 'الصنف: '||v_action.product_name else null end),
      v_action.reason, v_priority, v_needed_date,
      'whatsapp-action:'||v_action.id::text, 'whatsapp_review_v6'
    );
    v_target_id := nullif(v_result->>'followup_id','');
    if v_target_id is null then raise exception 'followup_creation_did_not_return_id'; end if;
    update public.whatsapp_conversation_actions set status='created',target_table='daily_followups',target_id=v_target_id,last_error=null,updated_at=now() where id=v_action.id;

  else
    raise exception 'action_type_requires_manual_handling';
  end if;

  insert into public.whatsapp_review_audit(source_id,action,actor_id,actor_name,actor_role,before_state,after_state,note)
  select v_action.source_id,'operational_action_materialized',a.id::text,coalesce(a.name,a.username),coalesce(a.role,a.staff_role),to_jsonb(v_action),
         jsonb_build_object('action_id',v_action.id,'target_table',case when v_action.action_type='customer_request' then 'customer_requests' else 'daily_followups' end,'target_id',v_target_id,'result',v_result),
         'تم تنفيذ إجراء تشغيلي من WhatsApp Review بعد إجراء المستخدم الصريح.'
  from public.staff_accounts a where a.id=public.dawaa_current_staff_account_id_strict() limit 1;

  return jsonb_build_object('ok',true,'already_created',false,'action_id',v_action.id,'target_id',v_target_id,'result',v_result);
end;
$function$
